const RECIPIENT='michael.kohler@brillinger.de';
const cart=new Map();
const customCart=[];
let customItemCounter=0;
let batteryType='';
let glueType='Alleskleber';
let edding400Color='Schwarz';
let edding3000Color='Schwarz';
let batteryPackSize='8';
const cableTiePackSizes={'BM-028':'50','BM-029':'100'};
const $=id=>document.getElementById(id);
let feedbackTimer;
function notify(message){$('feedback').textContent=message;clearTimeout(feedbackTimer);feedbackTimer=setTimeout(()=>{$('feedback').textContent='';},3500);}
function minimum(product){return product.min||1;}
function quantity(value){const number=Number(value);return Number.isInteger(number)&&number>=1&&number<=999?number:null;}
function escapeHtml(value){return value.replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));}
function invalidateOrder(){$('email-fallback').hidden=true;$('order-text').value='';}
function quantityControl(product,value,kind){const label=kind==='cart'?'Bestellmenge':'Menge';return `<div class="quantity"><button type="button" data-step="-1" aria-label="${label} für ${product.name} verringern">−</button><input type="number" min="${minimum(product)}" max="999" step="1" value="${value}" aria-label="${label} für ${product.name}" data-kind="${kind}" data-id="${product.id}"><button type="button" data-step="1" aria-label="${label} für ${product.name} erhöhen">+</button></div>`;}
const CATEGORIES=['Alle','Allgemein','Bürobedarf','Fahrzeugzubehör','Hygiene','Küche','Versand'];
let activeCategory='Alle';
let searchTerm='';
$('article-search').addEventListener('input',event=>{searchTerm=event.target.value.trim().toLocaleLowerCase('de');renderProducts();});
function renderProducts(){
  const categoryProducts=searchTerm?PRODUCTS:activeCategory===null?[]:activeCategory==='Alle'?PRODUCTS:PRODUCTS.filter(p=>p.category===activeCategory);
  const filtered=categoryProducts.filter(p=>!searchTerm||[p.name,p.category,p.unit].some(value=>value.toLocaleLowerCase('de').includes(searchTerm))).sort((a,b)=>{const karton=n=>/^Kartonagen\b/.test(n.name)?Number(n.name.match(/\((\d+)\)\s*$/)?.[1]||0):null;const ka=karton(a),kb=karton(b);return ka!==null&&kb!==null?ka-kb:a.name.localeCompare(b.name,'de',{numeric:true,sensitivity:'base'});});
  $('category-filters').innerHTML=CATEGORIES.map(category=>`<button type="button" class="category-button ${category===activeCategory?'active':''}" data-category="${category}" aria-pressed="${category===activeCategory}">${category}</button>`).join('');

  $('products').innerHTML=filtered.map(p=>`<article class="product"><div class="product-top">${p.image?`<img class="product-image" src="${p.image}" alt="${p.name} – Produktabbildung">`:`<span class="product-symbol" aria-hidden="true">${p.symbol}</span>`}</div><div class="product-body"><h3>${p.name}</h3><div class="unit">${p.unit}</div>${p.min?`<div class="unit">Mindestbestellmenge: ${p.min}</div>`:''}${['BM-028','BM-029'].includes(p.id)?`<label class="battery-label" for="pack-${p.id}">Packungsgröße auswählen</label><select class="battery-type" id="pack-${p.id}">${['50','100'].map(n=>`<option value="${n}" ${cableTiePackSizes[p.id]===n?'selected':''}>${n} Stück</option>`).join('')}</select>`:''}${p.id==='BU-001'?`<label class="battery-label" for="edding3000-color">Farbe auswählen</label><select class="battery-type" id="edding3000-color">${['Schwarz','Blau','Rot','Grün'].map(c=>`<option value="${c}" ${edding3000Color===c?'selected':''}>${c}</option>`).join('')}</select>`:''}${p.id==='BU-002'?`<label class="battery-label" for="edding400-color">Farbe auswählen</label><select class="battery-type" id="edding400-color">${['Schwarz','Blau','Rot','Grün'].map(c=>`<option value="${c}" ${edding400Color===c?'selected':''}>${c}</option>`).join('')}</select>`:''}${p.id==='BM-025'?`<label class="battery-label" for="glue-type">Kleberart</label><select class="battery-type" id="glue-type"><option value="Alleskleber" ${glueType==='Alleskleber'?'selected':''}>Alleskleber</option><option value="Sekundenkleber" ${glueType==='Sekundenkleber'?'selected':''}>Sekundenkleber</option></select>`:''}${p.id==='BM-022'?`<label class="battery-label" for="battery-type">Batterietyp / Größe</label><input class="battery-type" id="battery-type" type="text" maxlength="80" placeholder="z. B. AA, AAA, 9 V" value="${escapeHtml(batteryType)}" required><label class="battery-label" for="battery-pack-size">Packungsgröße</label><select class="battery-type" id="battery-pack-size"><option value="8" ${batteryPackSize==='8'?'selected':''}>8er-Pack</option><option value="24" ${batteryPackSize==='24'?'selected':''}>24er-Pack</option><option value="40" ${batteryPackSize==='40'?'selected':''}>40er-Pack</option></select>`:''}<div class="product-action">${quantityControl(p,minimum(p),'product')}<button type="button" class="primary" data-add="${p.id}">In den Warenkorb</button></div></div></article>`).join('');
  if(activeCategory===null&&!searchTerm)$('products').innerHTML='';
  else if(!filtered.length)$('products').innerHTML=searchTerm?'<p class="category-empty">Keine passenden Artikel gefunden.</p>':'<p class="category-empty">In dieser Kategorie sind noch keine Artikel hinterlegt.</p>';
}
renderProducts();

function renderCart(){const total=[...cart.values()].reduce((a,b)=>a+b,0)+customCart.reduce((a,p)=>a+p.amount,0);$('cart-count').textContent=total;$('position-count').textContent=`${cart.size+customCart.length} ${cart.size+customCart.length===1?'Position':'Positionen'}`;$('order-button').disabled=!(cart.size+customCart.length);$('cart-items').innerHTML=cart.size?[...cart].map(([id,amount])=>{const p=PRODUCTS.find(p=>p.id===id);return `<div class="cart-item"><h3>${p.name}</h3><p>${p.unit}${id==='BM-022'&&batteryType?' · Typ: '+escapeHtml(batteryType)+' · '+batteryPackSize+'er-Pack':''}${id==='BM-025'?' · '+glueType:''}${id==='BU-002'?' · Farbe: '+edding400Color:''}${id==='BU-001'?' · Farbe: '+edding3000Color:''}${cableTiePackSizes[id]?' · Packung: '+cableTiePackSizes[id]+' Stück':''}${p.min?` · Mindestbestellmenge: ${p.min}`:''}</p><div class="cart-controls">${quantityControl(p,amount,'cart')}<button type="button" class="remove" data-remove="${id}" aria-label="${p.name} aus dem Warenkorb entfernen">Entfernen</button></div></div>`;}).join(''):(customCart.length?'':'<p class="empty">Dein Warenkorb ist noch leer.<br>Wähle Artikel aus dem Sortiment.</p>');$('cart-items').innerHTML+=customCart.map(p=>`<div class="cart-item"><h3>${escapeHtml(p.name)} <small>(Sonstiger Artikel)</small></h3><p>${p.details?escapeHtml(p.details):'Individuelle Anfrage'}</p><div class="cart-controls"><div class="quantity"><button type="button" data-custom-step="-1" data-custom-id="${p.id}" aria-label="Menge verringern">−</button><input type="number" min="1" max="999" value="${p.amount}" data-custom-quantity="${p.id}" aria-label="Menge für ${escapeHtml(p.name)}"><button type="button" data-custom-step="1" data-custom-id="${p.id}" aria-label="Menge erhöhen">+</button></div><button type="button" class="remove" data-custom-remove="${p.id}">Entfernen</button></div></div>`).join('');$('cart-summary').innerHTML=(cart.size+customCart.length)?`<div class="summary">${total} Verpackungseinheiten insgesamt</div>`:'';}
document.addEventListener('click',event=>{const button=event.target.closest('button');if(!button)return;if(button.hasAttribute('data-category')){activeCategory=button.dataset.category;renderProducts();return;}if(button.hasAttribute('data-step')){const input=button.parentElement.querySelector('input');const product=PRODUCTS.find(p=>p.id===input.dataset.id);const min=minimum(product);const current=quantity(input.value)||min;input.value=Math.max(min,Math.min(999,current+Number(button.dataset.step)));if(input.dataset.kind==='cart'){cart.set(input.dataset.id,Number(input.value));invalidateOrder();renderCart();}return;}if(button.dataset.add){const id=button.dataset.add;if(id==='BM-022'&&!batteryType.trim()){notify('Bitte den Batterietyp angeben (z. B. AA oder AAA).');$('battery-type')?.focus();return;}const input=button.parentElement.querySelector('input');const amount=quantity(input.value);if(!amount||amount<minimum(PRODUCTS.find(p=>p.id===id))){notify('Bitte die Mindestbestellmenge beachten.');return;}const next=(cart.get(id)||0)+amount;if(next>999){notify('Pro Artikel sind maximal 999 Verpackungseinheiten möglich.');return;}cart.set(id,next);invalidateOrder();renderCart();notify(`${PRODUCTS.find(p=>p.id===id).name} zum Warenkorb hinzugefügt.`);}if(button.dataset.remove){cart.delete(button.dataset.remove);invalidateOrder();renderCart();notify('Artikel entfernt.');}});
document.addEventListener('input',event=>{if(event.target.id==='battery-type'){batteryType=event.target.value;invalidateOrder();}});
document.addEventListener('change',event=>{if(event.target.id.startsWith('pack-BM-02')&&cableTiePackSizes[event.target.id.slice(5)]){cableTiePackSizes[event.target.id.slice(5)]=event.target.value;invalidateOrder();renderCart();}if(event.target.id==='battery-pack-size'){batteryPackSize=event.target.value;invalidateOrder();renderCart();}if(event.target.id==='glue-type'){glueType=event.target.value;invalidateOrder();renderCart();}if(event.target.id==='edding400-color'){edding400Color=event.target.value;invalidateOrder();renderCart();}if(event.target.id==='edding3000-color'){edding3000Color=event.target.value;invalidateOrder();renderCart();}});
document.addEventListener('change',event=>{const input=event.target;if(input.dataset.kind==='cart'){const amount=quantity(input.value);if(!amount||amount<minimum(PRODUCTS.find(p=>p.id===input.dataset.id))){notify('Bitte die Mindestbestellmenge beachten.');input.value=cart.get(input.dataset.id);return;}cart.set(input.dataset.id,amount);invalidateOrder();renderCart();}});
$('order-form').addEventListener('input',invalidateOrder);
function buildOrder(name,department,note){return ['Hallo,','','bitte folgende Materialien bestellen:','',...[...cart].map(([id,amount])=>{const p=PRODUCTS.find(p=>p.id===id);return `${amount} × ${p.name}${id==='BM-022'?' ('+batteryType+', '+batteryPackSize+'er-Pack)':id==='BM-025'?' ('+glueType+')':id==='BU-002'?' (Farbe: '+edding400Color+')':id==='BU-001'?' (Farbe: '+edding3000Color+')':cableTiePackSizes[id]?' ('+cableTiePackSizes[id]+' Stück je Packung)':''} – ${cableTiePackSizes[id]?'1 Packung = '+cableTiePackSizes[id]+' Stück':p.unit}${p.supplier?'\nLieferant: '+p.supplier:''}${p.supplierArticleNumber?'\nArtikelnummer: '+p.supplierArticleNumber:''}${p.orderContact?'\nBestellkontakt: '+p.orderContact:''}${p.orderNote?'\nBestellhinweis: '+p.orderNote:''}`;}).flatMap(item=>[item,'']),...customCart.map(p=>`${p.amount} × ${p.name} (Sonstiger Artikel)${p.details?'\nWeitere Angaben: '+p.details:''}`).flatMap(item=>[item,'']),'',`Bestellt von: ${name}`,'',`Standort / Bereich: ${department}`, ...(note?[ '', `Anmerkung: ${note}` ]:[]),''].filter(line=>line!==null).join('\n');}
$('order-form').addEventListener('submit',event=>{event.preventDefault();if(!(cart.size+customCart.length))return;if(cart.has('BM-022')&&!batteryType.trim()){notify('Bitte bei Batterien den Batterietyp angeben.');$('battery-type')?.focus();return;}for(const input of $('cart-items').querySelectorAll('input')){const amount=quantity(input.value);if(!amount||amount<minimum(PRODUCTS.find(p=>p.id===input.dataset.id))){notify('Bitte die Mindestbestellmenge beachten.');input.focus();return;}cart.set(input.dataset.id,amount);}const name=$('customer').value.trim();const department=$('department').value.trim();if(!name||!department){notify('Bitte Name und Standort / Bereich ausfüllen.');return;}const body=buildOrder(name,department,$('note').value.trim());$('order-text').value=body;$('email-fallback').hidden=false;const subject=`Materialbestellung Brillinger – ${name.replace(/[\r\n]/g,' ')}`;window.location.href=`mailto:${RECIPIENT}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;notify('E-Mail vorbereitet. Bitte im E-Mail-Programm absenden.');});
$('copy-order').addEventListener('click',async()=>{try{await navigator.clipboard.writeText($('order-text').value);notify('Bestelltext kopiert.');}catch{$('order-text').focus();$('order-text').select();notify('Bitte den markierten Bestelltext manuell kopieren.');}});
renderCart();

/* Auf Smartphones zwischen Artikeln und Warenkorb wechseln. */
function syncMobileShopView(){
  const isCart=window.location.hash==='#warenkorb';
  const mobile=window.matchMedia('(max-width: 720px)').matches;
  document.body.classList.toggle('mobile-cart-view',mobile&&isCart);
  document.body.classList.toggle('custom-entry-view',window.location.hash==='#sonderartikel');
  if((mobile&&(isCart||window.location.hash==='#artikel'))||window.location.hash==='#sonderartikel')window.scrollTo(0,0);
}
window.addEventListener('hashchange',syncMobileShopView);
window.addEventListener('resize',syncMobileShopView);
syncMobileShopView();


/* Individuelle Artikel, die nicht im Katalog stehen. */
$('custom-product-form').addEventListener('submit',event=>{
 event.preventDefault();
 const name=$('custom-product-name').value.trim();
 const amount=quantity($('custom-product-amount').value);
 const details=$('custom-product-details').value.trim();
 if(!name||!amount){notify('Bitte Artikelbezeichnung und gültige Menge eingeben.');return;}
 customCart.push({id:++customItemCounter,name,amount,details});
 $('custom-product-form').reset();
 $('custom-product-amount').value='1';
 invalidateOrder();renderCart();notify(name+' zum Warenkorb hinzugefügt.');
});
document.addEventListener('click',event=>{
 const button=event.target.closest('button');
 if(!button)return;
 const id=Number(button.dataset.customId||button.dataset.customRemove);
 if(!id)return;
 const index=customCart.findIndex(p=>p.id===id);
 if(index<0)return;
 if(button.dataset.customRemove){customCart.splice(index,1);}
 else if(button.dataset.customStep){
  customCart[index].amount=Math.max(1,Math.min(999,customCart[index].amount+Number(button.dataset.customStep)));
 }
 invalidateOrder();renderCart();
});
document.addEventListener('change',event=>{
 const id=Number(event.target.dataset.customQuantity);
 if(!id)return;
 const p=customCart.find(item=>item.id===id);
 if(!p)return;
 const amount=quantity(event.target.value);
 if(!amount){event.target.value=p.amount;notify('Bitte eine gültige Menge eingeben.');return;}
 p.amount=amount;invalidateOrder();renderCart();
});

/* Abstand der fixierten Suche dynamisch an die Headerhöhe anpassen. */
function updateMobileStickyOffset(){
  const header=document.querySelector('header');
  if(header)document.documentElement.style.setProperty('--mobile-header-height',header.getBoundingClientRect().height+'px');
}
window.addEventListener('resize',updateMobileStickyOffset);
updateMobileStickyOffset();
